var a=`1335-carapulcra`;var i=`world-1335`;var n=`PE`;var r=`south-america`;var o=4;var s=174;var l={en:`Carapulcra`,ua:`Карапулькра`};var d={en:`Carapulcra is a dish from Peru featuring potato, pork shoulder, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used. Fresh potatoes replace chuño (traditional dried freeze-thawed potatoes); this is an adapted carapulcra, not a textural equivalent.`,ua:`Карапулькра, страва кухні країни Перу з такими основними складниками: картопля, свиняча лопатка, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Свіжа картопля замінює чуньйо (традиційну висушену виморожену картоплю); це адаптована карапулькра.`};var u=[{en:`Soak the sliced fresh potatoes briefly for this documented approximation; dried chuño would be rehydrated differently.`,ua:`Коротко замочіть нарізану свіжу картоплю для цієї задокументованої адаптації; сухе чуньйо відновлюють інакше.`,t:[`soaking-legumes`],m:80,i:[[`potato`,600,`g`],[`water`,1e3,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`pork-shoulder`,710,`g`],[`yellow-onion`,180,`g`],[`garlic`,5,`clove`],[`canola-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 80 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 80 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:80,i:[[`aji-panca-paste`,55,`g`],[`chicken-stock`,800,`ml`],[`peanut`,120,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,25,`g`]]}];var h={slug:a,id:i,country:`PE`,region:r,servings:4,minutes:174,title:l,text:d,steps:u};export{n as country,h as default,i as id,s as minutes,r as region,o as servings,a as slug,u as steps,d as text,l as title};